INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(15201, 'Psalms 135:14', 'Psalms', 135, 14, '&nbsp;ځکه چې مالِک خُدائ د خپلو خلقو اِنصاف کوى، او هغه په خپلو خِدمتګارانو رحم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15202, 'Psalms 135:15', 'Psalms', 135, 15, '&nbsp;د قومونو بُتان چې د سرو زرو او سپينو نه جوړ شوى دى، د انسانانو په لاسونو جوړ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15203, 'Psalms 135:16', 'Psalms', 135, 16, '&nbsp;د هغوئ خولې شته خو خبرې نۀ شى کولے، د هغوئ سترګې شته خو ليدل نۀ شى کولے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15204, 'Psalms 135:17', 'Psalms', 135, 17, '&nbsp;د هغوئ غوږونه شته خو اورېدل نۀ شى کولے، او نۀ هغوئ په خولۀ ساه اخستلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15205, 'Psalms 135:18', 'Psalms', 135, 18, '&nbsp;څوک چې دا بُتان جوړوى دوئ به هم د دې په شان وى څوک چې پرې ايمان لرى هغوئ به هم د دې په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15206, 'Psalms 135:19', 'Psalms', 135, 19, '&nbsp;اے د بنى اِسرائيل خاندانه د مالِک خُدائ ثناء ووايئ، اے د هارون خاندانه د مالِک خُدائ ثناء ووايئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15207, 'Psalms 135:20', 'Psalms', 135, 20, '&nbsp;اے د ليويانو خاندانه د مالِک خُدائ صِفت کوئ، او تاسو څوک چې د مالِک خُدائ نه يرېږئ د مالِک خُدائ ثناء صِفت کوئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15208, 'Psalms 135:21', 'Psalms', 135, 21, '&nbsp;د صيون نه دې د مالِک خُدائ ثناء صِفت وى، هغۀ ته دې ثناء صِفت وى څوک چې په يروشلم کښې اوسيږى. د مالِک خُدائ ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15209, 'Psalms 136:1', 'Psalms', 136, 1, '&nbsp;د مالِک خُدائ شُکر ګزارى وکړئ، ځکه چې هغه ښۀ دے. د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15210, 'Psalms 136:2', 'Psalms', 136, 2, '&nbsp;د خُدائ پاک شُکر ګزارى وکړئ، چې د معبودانو خُدائ پاک دے. د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15211, 'Psalms 136:3', 'Psalms', 136, 3, '&nbsp;د مالِک خُدائ شُکر ګزارى وکړئ چې د مالِکانو مالِک خُدائ دے. د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15212, 'Psalms 136:4', 'Psalms', 136, 4, '&nbsp;د هغۀ شُکر ګزارى وکړئ چې صرف هغه لوئې معجزې کوى، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15213, 'Psalms 136:5', 'Psalms', 136, 5, '&nbsp;او هغه چا چې آسمانونه يې په حِکمت سره پېدا کړل، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15214, 'Psalms 136:6', 'Psalms', 136, 6, '&nbsp;او د هغۀ شُکر ګزارى وکړئ چا چې زمکه د اوبو دپاسه خوره کړله، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15215, 'Psalms 136:7', 'Psalms', 136, 7, '&nbsp;او د هغۀ شُکر ګزارى وکړئ چا چې آسمانى رڼاګانې پېدا کړې، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15216, 'Psalms 136:8', 'Psalms', 136, 8, '&nbsp;نمر په ورځ باندې بادشاهى کوى، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15217, 'Psalms 136:9', 'Psalms', 136, 9, '&nbsp;سپوږمۍ او ستورى په شپه باندې حکومت کوى، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15218, 'Psalms 136:10', 'Psalms', 136, 10, '&nbsp;د هغۀ شُکر ګزارى وکړئ چا چې مِصريانو له وړومبى پېدا شوى هلاک کړل، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15219, 'Psalms 136:11', 'Psalms', 136, 11, '&nbsp;هغۀ بنى اِسرائيل د مِصر د مينځ نه راوويستل، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15220, 'Psalms 136:12', 'Psalms', 136, 12, '&nbsp;چا چې په هغه وخت د خپل طاقت او قدرت څرګندونه وکړه، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15221, 'Psalms 136:13', 'Psalms', 136, 13, '&nbsp;او د هغۀ شُکر ګزارى وکړئ چا چې بحرِقُلزم په مينځ دوه کړو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15222, 'Psalms 136:14', 'Psalms', 136, 14, '&nbsp;او هغۀ بنى اِسرائيل د دې په مينځ کښې بوتلل، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15223, 'Psalms 136:15', 'Psalms', 136, 15, '&nbsp;خو فِرعون سره د نوکرانو په بحرِقُلزم کښې غرق شو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15224, 'Psalms 136:16', 'Psalms', 136, 16, '&nbsp;او د هغۀ شُکر ګزارى وکړئ چا چې د خپلو خلقو په بيابان کښې لارښودنه وکړله، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15225, 'Psalms 136:17', 'Psalms', 136, 17, '&nbsp;د هغۀ شُکر ګزارى کوئ چا چې لوئ بادشاهان رانسکور کړل، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15226, 'Psalms 136:18', 'Psalms', 136, 18, '&nbsp;او هغۀ تکړه بادشاهان هلاک کړل، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15227, 'Psalms 136:19', 'Psalms', 136, 19, '&nbsp;سيحون د اموريانو بادشاه يې مړ کړلو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15228, 'Psalms 136:20', 'Psalms', 136, 20, '&nbsp;عوج د بسن بادشاه يې مړ کړلو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15229, 'Psalms 136:21', 'Psalms', 136, 21, '&nbsp;او هغۀ د هغوئ مُلک دوئ ته په ميراث کښې ورکړو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15230, 'Psalms 136:22', 'Psalms', 136, 22, '&nbsp;او په ميراث کښې يې خِدمتګار بنى اِسرائيل ته ورکړو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15231, 'Psalms 136:23', 'Psalms', 136, 23, '&nbsp;د هغۀ شُکر ګزارى وکړئ چا ته چې مونږ د کمزورتيا په حالت کښې ياد وُو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15232, 'Psalms 136:24', 'Psalms', 136, 24, '&nbsp;او مونږ يې د خپلو دشمنانو نه خلاص کړلو، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15233, 'Psalms 136:25', 'Psalms', 136, 25, '&nbsp;او څوک چې هر يو مخلوق ته رزق ورکوى، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15234, 'Psalms 136:26', 'Psalms', 136, 26, '&nbsp;د آسمانونو د خُدائ شُکر ادا کړئ، د هغۀ مينه ابدى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15235, 'Psalms 137:1', 'Psalms', 137, 1, '&nbsp;نو مونږ د بابل د سيند په غاړه کښېناستلو او ومو ژړل، هرکله چې صيون مونږ ته به راپه ياد شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15236, 'Psalms 137:2', 'Psalms', 137, 2, '&nbsp;هلته په چنارونو کښې مونږ خپل ربابُونه راوېزاند کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15237, 'Psalms 137:3', 'Psalms', 137, 3, '&nbsp;ځکه چې هلته زمونږ قابضينو په مونږ سندرې وئيلى، او مونږ ته تکليف رسوونکو زمونږ نه د خوشحالۍ د سندرو خواهش کولو، دوئ مونږ ته وئيل چې، ”مونږ ته د صيون د سندرو نه يوه ووايئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15238, 'Psalms 137:4', 'Psalms', 137, 4, '&nbsp;نو مونږ د مالِک خُدائ سندرې څنګه ووايو هرکله چې مونږ په پردى مُلک کښې يُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15239, 'Psalms 137:5', 'Psalms', 137, 5, '&nbsp;کۀ چرې زۀ تا هېر کړمه يروشلم، نو زما ښى لاس نه دې خپل هُنر هېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15240, 'Psalms 137:6', 'Psalms', 137, 6, '&nbsp;زما ژبه دې زما تالو پورې ونښلى، کۀ چرې تۀ ما ته ياد نۀ يې، او کۀ چرې زۀ يروشلم د ټولو نه خپله لويه خوشحالى نۀ ګڼم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15241, 'Psalms 137:7', 'Psalms', 137, 7, '&nbsp;اے مالِکه خُدايه، ادوميان راياد کړه، چې څۀ يې کړى وُو، په کومه ورځ چې يروشلم رانسکور شوے وو. هغوئ چغې وهلې چې، ”وران يې کړئ، او چې د بنيادونو پورې يې وران کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15242, 'Psalms 137:8', 'Psalms', 137, 8, '&nbsp;اے د بابل خلقو، تباه شئ، هغه دې خوشحاله وى څوک چې تا ته بدل درکړى، کوم کارونه چې تا مونږ سره وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15243, 'Psalms 137:9', 'Psalms', 137, 9, '&nbsp;هغه به خوشحاله وى څوک چې ستا ماشومان ګرفتاروى، او د ګټانو سره ورله ډغرې ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15244, 'Psalms 138:1', 'Psalms', 138, 1, '&nbsp;زۀ به د زړۀ د اخلاصه، ستا ثناء صِفت وکړم، اے مالِکه خُدايه، او د نورو معبودانو په وړاندې به زۀ ستا د شُکر ګزارۍ سندرې ووايم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15245, 'Psalms 138:2', 'Psalms', 138, 2, '&nbsp;زۀ به ستا مقدس کور طرف ته سجده وکړم، او زۀ به ستا د نوم ثناء صِفت ادا کړم، ځکه چې تۀ ډېر مينه ناک او وفادار يې، او تا په ټولو څيزونو باندې خپل نوم او کلام اوچت کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15246, 'Psalms 138:3', 'Psalms', 138, 3, '&nbsp;ما چې کله هم تا ته سوال زارى کړې ده، تا قبوله کړې ده، تا زۀ په طاقت ورکولو تکړه او زړَور کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15247, 'Psalms 138:4', 'Psalms', 138, 4, '&nbsp;اے مالِکه خُدايه، د دُنيا ټول بادشاهان دې ستا ثناء صِفت وکړى، چې کله دوئ ستا د خولې کلام واورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15248, 'Psalms 138:5', 'Psalms', 138, 5, '&nbsp;دوئ دې د مالِک خُدائ د طريقو ثناء صِفت وکړى، ځکه چې د مالِک خُدائ جلال لوئ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15249, 'Psalms 138:6', 'Psalms', 138, 6, '&nbsp;کۀ څۀ هم چې مالِک خُدائ ډېر اوچت دے، خو بيا هم د ښکته خلقو خيال ساتى، خو هغه کبرژن د ډېر لرې نه پېژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15250, 'Psalms 138:7', 'Psalms', 138, 7, '&nbsp;زۀ کۀ څۀ هم د مصيبتونو په مينځ کښې ګرځم، تۀ زما ژوندون بچ کوې. تۀ خپل لاس زما د دشمنانو د غصې په خلاف راوږدوې، د خپل ښى لاس سره دې ما بچ کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15251, 'Psalms 138:8', 'Psalms', 138, 8, '&nbsp;مالِک خُدائ به زما دپاره خپل مقصد پوره کړى، ستا مينه، اے مالِکه خُدايه، د تل دپاره پاتې کيږى، د خپلو لاسونو کارونه مۀ پرېږده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15252, 'Psalms 139:1', 'Psalms', 139, 1, '&nbsp;اے مالِکه خُدايه، تا زۀ معلوم کړے يم او تۀ ما پېژنې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15253, 'Psalms 139:2', 'Psalms', 139, 2, '&nbsp;تا ته زما د ناستې پاستې پته ده، او زۀ کۀ لرې هم يم تۀ زما په سوچونو پوهېږې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15254, 'Psalms 139:3', 'Psalms', 139, 3, '&nbsp;زۀ کۀ ګرځم او کۀ ملاست يم، نو تا ته زما د ټولو کارونو پته ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15255, 'Psalms 139:4', 'Psalms', 139, 4, '&nbsp;خبره لا زما د خولې نه وتلې نۀ وى، چې تۀ په هغې پوره خبر يې، اے مالِکه خُدايه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15256, 'Psalms 139:5', 'Psalms', 139, 5, '&nbsp;زما نه مخکښې او وروستو تۀ يې، او تا د خپل برکت لاس په ما اېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15257, 'Psalms 139:6', 'Psalms', 139, 6, '&nbsp;دغه شان پوهه زما دپاره ډېره حېرانونکې ده، او دا خبره زما د عقل نه لويه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15258, 'Psalms 139:7', 'Psalms', 139, 7, '&nbsp;زۀ به ستا د روح نه چرته لاړ شم؟ ستا د حضور نه به چرته وتښتم؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15259, 'Psalms 139:8', 'Psalms', 139, 8, '&nbsp;کۀ چرې زۀ آسمان ته هم وخېژم، تۀ هلته يې، کۀ چرې زۀ په قبر کښې هم څملم، ته هلته يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15260, 'Psalms 139:9', 'Psalms', 139, 9, '&nbsp;کۀ چرې زۀ د سبا په وزرو سور شم، کۀ چرې زۀ د سمندر په لرې غاړه اوسېږم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15261, 'Psalms 139:10', 'Psalms', 139, 10, '&nbsp;هلته به ستا لاس زما لارښودنه وکړى، او ستا قدرت به ما په تېزۍ سره راونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15262, 'Psalms 139:11', 'Psalms', 139, 11, '&nbsp;کۀ چرې زۀ دا ووايم چې، ”تيارۀ به ضرور ما ستا نه پټ کړى، او زما نه ګېرچاپېره رڼا به په شپه بدله شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15263, 'Psalms 139:12', 'Psalms', 139, 12, '&nbsp;خو تيارۀ به ستا دپاره تيارۀ نۀ وى، شپه به لکه د ورځ په شان ځليږى. ځکه چې تيارۀ به ستا دپاره د رڼا په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15264, 'Psalms 139:13', 'Psalms', 139, 13, '&nbsp;ځکه چې تا زما دننه هر څۀ پېدا کړل، او زۀ تا د مور په ګېډه کښې يو ځائ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15265, 'Psalms 139:14', 'Psalms', 139, 14, '&nbsp;زۀ ستا ثناء صِفت کومه ځکه چې زما د بدن جوړښت عجيبه او ويرونکے دے، ستا کارونه عجيبه دى او زۀ په دې ښۀ پوهېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15266, 'Psalms 139:15', 'Psalms', 139, 15, '&nbsp;زما د بدن ډانچه ستا نه پټه نۀ وه کله چې زۀ په پټ ځائ کښې جوړېدلم، او کله چې زۀ د زمکې په ژوره کښې جوړېدلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15267, 'Psalms 139:16', 'Psalms', 139, 16, '&nbsp;ستا سترګو زما نامکمله بدن وليدلو. او تا د شروع نه هغه ټولې ورځې چې زما د ژوند دپاره مقرر کړې وې هغه دې په خپل کِتاب کښې وليکلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15268, 'Psalms 139:17', 'Psalms', 139, 17, '&nbsp;ستا خيالونه ما ته څومره قيمتى دى، پاکه خُدايه، او دا څومره بې‌حسابه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15269, 'Psalms 139:18', 'Psalms', 139, 18, '&nbsp;کۀ چرې هغه وشمارم، نو د شګو نه ډېر دى. او زۀ چې کله راويښ شم، نو بيا هم تا سره يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15270, 'Psalms 139:19', 'Psalms', 139, 19, '&nbsp;کاش چې تۀ بدکاران هلاکوې، اے پاکه خُدايه، او وينو ته تږى ناست زما نه لرې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15271, 'Psalms 139:20', 'Psalms', 139, 20, '&nbsp;دوئ تا پسې قصداً بدې خبرې کوى، او مخالفين دې نوم بې‌فائدې اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15272, 'Psalms 139:21', 'Psalms', 139, 21, '&nbsp;مالِکه خُدايه، ولې زۀ د هغوئ نه نفرت ونۀ کړم څوک چې ستا نه نفرت کوى؟ او د هغوئ نه کرکه ونۀ کړم څوک چې ستا مخالفت کوى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15273, 'Psalms 139:22', 'Psalms', 139, 22, '&nbsp;زۀ بلکل د هغوئ نه نفرت کوم څوک چې ستا نه نفرت کوى، او هغوئ خپل دشمنان ګڼم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15274, 'Psalms 139:23', 'Psalms', 139, 23, '&nbsp;پاکه خُدايه، ما ولټوه، او زما زړۀ وپېژنه، او تۀ زما امتحان واخله او زما د پرېشانۍ په خيالونو ځان پوهه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15275, 'Psalms 139:24', 'Psalms', 139, 24, '&nbsp;ما ته وګوره کۀ چرې کومه غلطه طريقه په ما کښې وى، ما د تل ژوندون لارو ته رهنمائى کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15276, 'Psalms 140:1', 'Psalms', 140, 1, '&nbsp;اے مالِکه خُدايه، د بدکارانو نه ما بچ کړه، او د ظالمانو انسانانو نه ما وساته،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15277, 'Psalms 140:2', 'Psalms', 140, 2, '&nbsp;او څوک چې د شرارت منصوبې په خپلو زړونو کښې جوړوى او هره ورځ جنګ توده‌وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15278, 'Psalms 140:3', 'Psalms', 140, 3, '&nbsp;دوئ خپلې ژبې لکه د ښامار په شان تېروى، او د چمچمار زهر يې په شونډو پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15279, 'Psalms 140:4', 'Psalms', 140, 4, '&nbsp;اے مالِکه خُدايه، ما د بدکارانو د لاس نه محفوظ کړه، او ما د ظالمانو نه بچ کړه، څوک چې زما د پښو ګېرولو دپاره منصوبې جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15280, 'Psalms 140:5', 'Psalms', 140, 5, '&nbsp;کبرژنو سړو ما ته پټ دامونه اېښى دى، او دوئ خپل جالونه خوارۀ کړى دى. او زما په لارو کښې يې دامونه اېښى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15281, 'Psalms 140:6', 'Psalms', 140, 6, '&nbsp;ما مالِک خُدائ ته ووئيل، تۀ زما خُدائ پاک يې. اے مالِکه خُدايه، د رحم دپاره زما سوال زارى واوره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15282, 'Psalms 140:7', 'Psalms', 140, 7, '&nbsp;اے قادره مالِکه خُدايه، زما قوى خلاصونکيه، څوک چې د جنګ په ورځ زما سر پټوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15283, 'Psalms 140:8', 'Psalms', 140, 8, '&nbsp;د بدکارانو ارمانونه تۀ مۀ پوره کوه، اے مالِکه خُدايه، او د دوئ منصوبې کاميابېدو ته مۀ پرېږده، هسې نه چې دوئ مغروره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15284, 'Psalms 140:9', 'Psalms', 140, 9, '&nbsp;او څوک چې ما نه راتاو دى د هغوئ سرونه دې په مصيبت کښې راګېر شى، او په هغه مصيبت کښې چې کوم د هغوئ شونډو جوړ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15285, 'Psalms 140:10', 'Psalms', 140, 10, '&nbsp;بلې شوې سکروټې دې په هغوئ راپرېوځى، او هغوئ دې په اور کښې وغورزولے شى، او هغوئ دې چکړو دلدل ته وغورزيږى چې بيا ترې راوتلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15286, 'Psalms 140:11', 'Psalms', 140, 11, '&nbsp;غېبت کوونکى دې په دې مُلک کښې کامياب نۀ شى، او په ظالمانو دې ناګهانه افت راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15287, 'Psalms 140:12', 'Psalms', 140, 12, '&nbsp;زۀ په دې پوهېږمه چې مالِک خُدائ به غريبانانو له اِنصاف ورکړى، او هغه د حاجتمندو مقدمه په خپل لاس کښې اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15288, 'Psalms 140:13', 'Psalms', 140, 13, '&nbsp;او بې‌شکه چې نېکان به ستا د نوم ثناء صِفت وکړى، او صادقان به ستا په حضور کښې ژوند وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15289, 'Psalms 141:1', 'Psalms', 141, 1, '&nbsp;اے مالِکه خُدايه، زۀ تا ته سوال زارى کومه ما له زر راشه، زما آواز اوره کله چې زۀ درته سوال کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15290, 'Psalms 141:2', 'Psalms', 141, 2, '&nbsp;زما دُعا دې ستا په حضور کښې د خوشبو په شان شى، او زما د لاسونو اوچتول دې تا ته لکه د ماښام د قربانۍ په شان قبول شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15291, 'Psalms 141:3', 'Psalms', 141, 3, '&nbsp;اے مالِکه خُدايه، زما خولۀ قابو کړه، او زما په شونډو نظر وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15292, 'Psalms 141:4', 'Psalms', 141, 4, '&nbsp;زما زړۀ دې په بدو لارو لاړ نۀ شى، او نۀ دې د بدکارو په کارونو کښې حِصه واخلى. او نۀ دې خطاکارو سره مل شى، ما د هغه خلقو د خوندور خوراکونو د خوړلو نه وساته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15293, 'Psalms 141:5', 'Psalms', 141, 5, '&nbsp;کۀ نېک سړے ما وډبوى دا به مهربانى وى، او د هغۀ رټل به زما دپاره په سر باندې د تېلو په شان وى، او زما سر به د دې تېلو نه اِنکار نۀ کوى، خو زما دُعا به تل د بدعملو د کارونو په خلاف وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15294, 'Psalms 141:6', 'Psalms', 141, 6, '&nbsp;کله چې د دوئ بادشاهان د کمرونو نه راوغورزيږى، نو بدعمله به دا زده کړى چې زما وېنا خوږه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15295, 'Psalms 141:7', 'Psalms', 141, 7, '&nbsp;لکه څنګه چې د زمکې په قلبې سره کاڼى برسيره شى، نو دغه شان به زمونږ هډُوکى د قبر په خولۀ کښې خوارۀ وارۀ پراتۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15296, 'Psalms 141:8', 'Psalms', 141, 8, '&nbsp;خو زما سترګې ستا په طرف دى، اے قادر مطلق خُدايه، او ستا نه پناه غواړم ما مرګ ته مۀ حواله کوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15297, 'Psalms 141:9', 'Psalms', 141, 9, '&nbsp;ما د هغه لټ نه وساته کوم چې دوئ زما دپاره اېښے دے، ما د هغه دامونو نه وساته چې بدعملو زما دپاره خوارۀ کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15298, 'Psalms 141:10', 'Psalms', 141, 10, '&nbsp;بدعمله دې په خپلو دامونو کښې راګېر شى، چې داسې زۀ ترې بچ شمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15299, 'Psalms 142:1', 'Psalms', 142, 1, '&nbsp;زۀ په زوره مالِک خُدائ ته ‎ژړا کوم، او ما د رحم دپاره مالِک خُدائ ته آواز وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(15300, 'Psalms 142:2', 'Psalms', 142, 2, '&nbsp;زۀ خپل فريادونه د هغۀ په وړاندې کوم، د هغۀ په وړاندې زۀ خپل مصيبت بيانوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');